require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/business_helpers.php';require_login();$error='';$selected=(int)($_GET['car_id']??0);$cars=$conn->query("SELECT id,car_name,plate_number FROM cars WHERE status='IN_STOCK' ORDER BY car_name");
if($_SERVER['REQUEST_METHOD']==='POST'){$car=(int)($_POST['car_id']??0);$name=trim($_POST['customer_name']??'');$phone=trim($_POST['customer_phone']??'');$license=trim($_POST['license_number']??'');$date=str_replace('T',' ',$_POST['test_date']??'');if(strlen($date)===16)$date.=':00';$notes=trim($_POST['notes']??'');$uid=(int)$_SESSION['user_id'];if(!$car||$name===''||$date===''){$error='Car, customer and test-drive date are required.';}else{$cid=find_or_create_customer($conn,$name,$phone,'',$uid);$st=$conn->prepare('INSERT INTO test_drives(car_id,customer_id,customer_name,customer_phone,license_number,test_date,notes,created_by) VALUES(?,?,?,?,?,?,?,?)');$st->bind_param('iisssssi',$car,$cid,$name,$phone,$license,$date,$notes,$uid);if($st->execute()){$tid=(int)$st->insert_id;car_sales_audit($conn,'CREATE','test_drive',$tid,'Scheduled test drive for '.$name.'.',null,['car_id'=>$car,'customer_id'=>$cid,'test_date'=>$date]);set_flash('success','Test drive scheduled.');redirect_to('backend/testdrives/index.php');}else{$error='Could not schedule test drive.';}}}
$page_title='Schedule Test Drive';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><h1 class="page-title">Schedule Test Drive</h1><div class="card form-card"><?php if($error):?><div class="flash-message error" style="position:static"><?=e($error)?></div><?php endif;?><form method="post"><div class="form-group"><label>Car *</label><select name="car_id" required><option value="">Select car</option><?php while($c=$cars->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$selected===(int)$c['id']?'selected':''?>><?=e($c['car_name'].' / '.car_sales_plate_label($c['plate_number']))?></option><?php endwhile;?></select></div><div class="form-row"><div class="form-group"><label>Customer Name *</label><input name="customer_name" required></div><div class="form-group"><label>Phone</label><input name="customer_phone"></div></div><div class="form-row"><div class="form-group"><label>Driving Licence Number</label><input name="license_number"></div><div class="form-group"><label>Date & Time *</label><input type="datetime-local" name="test_date" required></div></div><div class="form-group"><label>Notes</label><textarea name="notes" rows="3"></textarea></div><button class="btn btn-green">Save</button><a class="btn btn-dark" href="index.php">Cancel</a></form></div></div><?php include __DIR__.'/../includes/footer.php';?>
